create or replace function public.refresh_user_leaderboard() returns void language plpgsql security definer set search_path=public as $$ begin delete from public.community_leaderboard; insert into public.community_leaderboard (user_id, display_name, username, points, level, streak, total_check_ins, total_reviews, rank) select p.id, coalesce(p.display_name,p.username,'Kleenest member'), p.username, coalesce(p.points,0), coalesce(p.level,1), coalesce(p.streak,0), coalesce(p.total_check_ins,0), coalesce(p.total_reviews,0), row_number() over(order by coalesce(p.points,0) desc, coalesce(p.total_check_ins,0) desc, coalesce(p.total_reviews,0) desc, p.id) from public.profiles p where coalesce(p.is_suspended,false)=false; end; $$; create or replace function public.refresh_business_metric_leaderboards() returns void language plpgsql security definer set search_path=public as $$ begin delete from public.business_metric_leaderboards; insert into public.business_metric_leaderboards (business_id, business_name, metric, value, rank) select x.business_id,x.business_name,x.metric,x.value,row_number() over(partition by x.metric order by x.value desc,x.business_id) from (select b.id business_id,b.name business_name,'check_ins' metric,count(c.id)::numeric value from public.businesses b left join public.locations l on l.business_id=b.id left join public.check_ins c on c.location_id=l.id group by b.id,b.name union all select b.id,b.name,'reviews',count(r.id)::numeric from public.businesses b left join public.locations l on l.business_id=b.id left join public.reviews r on r.location_id=l.id group by b.id,b.name union all select b.id,b.name,'favorites',count(f.id)::numeric from public.businesses b left join public.locations l on l.business_id=b.id left join public.favorites f on f.location_id=l.id group by b.id,b.name) x; end; $$; grant execute on function public.refresh_user_leaderboard() to authenticated; grant execute on function public.refresh_business_metric_leaderboards() to authenticated;
